documents.items_spec:
yamaa: "1.0"
type: spec
domain: IT
keys: [SEQ]
input:
  ODM: {path: odm.xml, empty_string: present}
output:
  path: items.csv
  columns: [SEQ, REPEAT, ITEM, NAME, VALUE, PRESENT, ISNULL]
columns:
  - {name: SEQ, type: int, derivation: ODM.SourceOrdinal}
  - {name: REPEAT, type: str, derivation: ODM.ItemGroupRepeatKey}
  - {name: ITEM, type: str, derivation: ODM.ItemOID}
  - {name: NAME, type: str, derivation: ODM.ItemName}
  - {name: VALUE, type: str, derivation: ODM.Value}
  - {name: PRESENT, type: str, derivation: ODM.ValuePresent}
  - {name: ISNULL, type: str, derivation: ODM.IsNull}
